36 | export function formatApiErrorDetail(detail: unknown, status: number): string {
37 |   if (typeof detail === "string") return detail;
38 |   if (Array.isArray(detail)) {
39 |     const messages = detail.flatMap((item) => {
40 |       if (!item || typeof item !== "object") return [];
41 |       const issue = item as { loc?: unknown; msg?: unknown };
42 |       const location = Array.isArray(issue.loc)
43 |         ? issue.loc.map(String).filter((part) => part !== "body").join(".")
44 |         : "request";
45 |       const message =
46 |         typeof issue.msg === "string" ? issue.msg : JSON.stringify(item);
47 |       return [`${location || "request"}: ${message}`];
48 |     });
49 |     if (messages.length) return messages.join("; ");
50 |   }
51 |   if (detail && typeof detail === "object") return JSON.stringify(detail);
52 |   return `Request failed with status ${status}`;
53 | }
